/**
 * Select a range of cells.
 *
 * @param AddressRange|array<int>|CellAddress|int|string $coordinate A simple string containing a Cell range like 'A1:E10'
 *              or passing in an array of [$fromColumnIndex, $fromRow, $toColumnIndex, $toRow] (e.g. [3, 5, 6, 8]),
 *              or a CellAddress or AddressRange object.
 *
 * @return $this
 */
public function setSelectedCells($coordinate)
{
    if (is_string($coordinate)) {
        $coordinate = Validations::definedNameToCoordinate($coordinate, $this);
    }
    $coordinate = Validations::validateCellOrCellRange($coordinate);

    [$worksheetName, $coordinate] = self::extractSheetTitle($coordinate, true);
    if (!empty($worksheetName)) {
        $worksheetName = str_replace("''", "'", trim($worksheetName, "'"));
        $currentTitle = (string) $this->getTitle();
        if (mb_convert_case($worksheetName, MB_CASE_UPPER, 'UTF-8') !== mb_convert_case($currentTitle, MB_CASE_UPPER, 'UTF-8')) {
            throw new Exception('Invalid Worksheet');
        }
    }

    if (Coordinate::coordinateIsRange($coordinate)) {
        [$first] = Coordinate::splitRange($coordinate);
        $this->activeCell = $first[0];
    } else {
        $this->activeCell = $coordinate;
    }
    $this->selectedCells = $coordinate;

    return $this;
}

